package cmd

import("encoding/json";"fmt";"time";"github.com/joshyorko/rcc/buildcoord";"github.com/spf13/cobra")
type coordinationResult struct{ Key buildcoord.BuildKey `json:"key"`; Claim buildcoord.Claim `json:"claim"`; Outcome buildcoord.Outcome `json:"outcome"`; Error string `json:"error,omitempty"` }
func newEnvironmentCoordinateCommand()*cobra.Command{var root,spec,platform,builder,owner string;var ttl time.Duration;var jsonOut bool;claim:=&cobra.Command{Use:"claim",Args:cobra.NoArgs,SilenceUsage:true,RunE:func(cmd *cobra.Command,_ []string)error{if !jsonOut{return fmt.Errorf("--json is required")};k:=buildcoord.BuildKey{SpecificationDigest:spec,Platform:platform,BuilderCompatibility:builder};c:=buildcoord.NewFilesystem(root,nil);cl,out,err:=c.ClaimContext(cmd.Context(),k,owner,ttl);r:=coordinationResult{Key:k,Claim:cl,Outcome:out};if err!=nil{r.Error=err.Error()};if e:=json.NewEncoder(cmd.OutOrStdout()).Encode(r);e!=nil{return e};return err}};claim.Flags().StringVar(&root,"root","","Coordinator state root");claim.Flags().StringVar(&spec,"specification","","Specification digest");claim.Flags().StringVar(&platform,"platform","","Compatibility platform");claim.Flags().StringVar(&builder,"builder","","Builder compatibility");claim.Flags().StringVar(&owner,"owner","","Build owner identity");claim.Flags().DurationVar(&ttl,"ttl",time.Minute,"Claim lease duration");claim.Flags().BoolVar(&jsonOut,"json",false,"Write JSON result");rootCmd:=&cobra.Command{Use:"coordinate",Short:"Coordinate optional cold environment builds.",Args:cobra.NoArgs};rootCmd.AddCommand(claim);return rootCmd}
